/** 进程内：同一规范会话根上的 mutation 串行（跨进程那一半是文件锁）。
 *  入链顺序在**调用时同步确定**，不依赖 `realpath` 的回程顺序（两次回程快慢不受调用顺序保证）。
 *  不同会话根之间的票据互不阻塞（隔离）。 */
interface MutationTicket {
  /** 本票据会话根的解析结果；用于判断更早的票据是否落在同一个根上。 */
  readonly rootPromise: Promise<string>;
  /** 本票据临界区结束（含出错释放）时兑现。 */
  readonly done: Promise<void>;
}
/** 在途票据，按调用顺序追加；票据完成即移除，避免无界增长。 */
const inflight: MutationTicket[] = [];
const lockHandles = new Map<string, FileHandle>();

/** 在会话根的临界区里执行 `operation`：进程内串行 + 跨进程文件锁。
 *  入链顺序**在调用时同步确定**：先把票据压入 `inflight`（此刻的先后即调用顺序），
 *  再各自等 `realpath` 得到规范根；只与「更早入链、且解析到同一个根」的票据串行——
 *  于是 realpath 回程颠倒也不会让后来的调用抢跑，而不同根的会话互不阻塞。 */
export async function withSessionMutation<T>(sessionsRoot: string, operation: () => Promise<T>): Promise<T> {
  let resolveDone!: () => void;
  const done = new Promise<void>((resolveDoneGate) => { resolveDone = resolveDoneGate; });
  const ticket: MutationTicket = { rootPromise: realpath(sessionsRoot), done };
  // 同步快照更早入链的票据（顺序即调用顺序），再把自己追加到队尾。
  const earlier = inflight.slice();
  inflight.push(ticket);
  try {
    const root = await ticket.rootPromise;
    // 只取「更早且同一个根」的票据里最后一个的 done 作闸门：不同根不受牵连。
    let gate: Promise<void> = Promise.resolve();
    for (const prior of earlier) {
      const priorRoot = await prior.rootPromise.catch(() => null);
      if (priorRoot === root) gate = prior.done;
    }
    await gate.catch(() => undefined);
    await acquireRootLock(root);
    try {
      return await operation();
    } finally {
      await releaseRootLock(root);
    }
  } finally {
    resolveDone();
    const index = inflight.indexOf(ticket);
    if (index >= 0) inflight.splice(index, 1);
  }
}

